//! Wire `project/scripts/*.rs` into the binary's module tree.
//!
//! The dev-facing rule for an Ocarina project is "scripts live in
//! `project/scripts/`"; they're real Rust files, but the engine
//! binary that hosts them is plumbing the dev shouldn't have to
//! think about. This build script bridges the two:
//!
//! 1. Walk `project/scripts/` for every `.rs` file.
//! 2. Emit a `scripts.rs` into `OUT_DIR` containing one
//!    `#[path = "/abs/path/to/project/scripts/foo.rs"] pub mod foo;`
//!    line per file.
//! 3. `main.rs` `include!()`s that generated file. Each script file
//!    becomes a top-level module of the host binary, its
//!    `#[derive(OcarinaScript)]` runs at link time, and its
//!    inventory submission lights up.
//!
//! Cargo reruns this script whenever a file in `project/scripts/` is
//! added, removed, or modified, so editing a script triggers a
//! recompile of the host binary.

use std::env;
use std::fs;
use std::io::Write;
use std::path::PathBuf;

fn main() {
    let manifest_dir =
        PathBuf::from(env::var("CARGO_MANIFEST_DIR").expect("CARGO_MANIFEST_DIR set by cargo"));
    let scripts_dir = manifest_dir.join("project").join("scripts");
    let out_dir = PathBuf::from(env::var("OUT_DIR").expect("OUT_DIR set by cargo"));
    let dest = out_dir.join("scripts.rs");

    // Re-run if the directory itself changes (file added/removed).
    println!("cargo:rerun-if-changed={}", scripts_dir.display());

    let mut out = fs::File::create(&dest).expect("create scripts.rs");
    writeln!(
        out,
        "// Generated by build.rs from project/scripts/*.rs — do not edit."
    )
    .unwrap();

    if !scripts_dir.is_dir() {
        // No scripts/ folder: the file stays empty, the binary still
        // compiles. The user might add scripts later.
        return;
    }

    let mut entries: Vec<PathBuf> = fs::read_dir(&scripts_dir)
        .expect("read scripts dir")
        .flatten()
        .map(|e| e.path())
        .filter(|p| p.is_file() && p.extension().and_then(|s| s.to_str()) == Some("rs"))
        .collect();
    // Stable order so generated code is deterministic.
    entries.sort();

    for path in entries {
        // Re-run if any individual script changes.
        println!("cargo:rerun-if-changed={}", path.display());

        let stem = path
            .file_stem()
            .and_then(|s| s.to_str())
            .expect("script filename should be UTF-8")
            .to_string();
        if !is_ident(&stem) {
            // Skip files whose names aren't valid Rust identifiers
            // (e.g. `my-script.rs`). Could `_`-mangle, but failing
            // loudly is friendlier than silently dropping a script.
            panic!(
                "script file `{}` has a non-identifier stem; rename to use \
                 only ASCII letters, digits, and underscores",
                path.display()
            );
        }
        let abs = path.canonicalize().unwrap_or_else(|_| path.clone());
        writeln!(out, "#[path = {:?}]", abs.display().to_string()).unwrap();
        writeln!(out, "pub mod {stem};").unwrap();
    }
}

fn is_ident(s: &str) -> bool {
    let mut chars = s.chars();
    match chars.next() {
        Some(c) if c.is_ascii_alphabetic() || c == '_' => {}
        _ => return false,
    }
    chars.all(|c| c.is_ascii_alphanumeric() || c == '_')
}
